{
  "aggregate_id": "DEF-LVMC-11-02-082::electric_bicycle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "underdetermined",
      "reason": "The first rideable-device alternative does not require an electric motor, so an admitted human-powered bicycle need not carry the proposed covering class."
    },
    {
      "class": "ru.bus",
      "verdict": "underdetermined",
      "reason": "The bus contract specifies passenger capacity but supplies no wheel-count or equipment restriction that makes every member incompatible with the admitting words."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "This class describes a pedestrian person rather than the rideable device to which the quoted equipment requirements apply."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "underdetermined",
      "reason": "Commercial mass or licensing does not establish that every admitted rideable device is a bicycle with an assisting electric motor, as the covering contract requires."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The admitting words expressly reach bicycles equipped with operable pedals, a rider's seat and an electric motor, subject to the posted power and class requirements."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The controlling definition expressly states that the term does not include an electric scooter."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "underdetermined",
      "reason": "Neither emergency designation nor the rideable-device alternative establishes that every admitted member satisfies the covering contract's bicycle and assisting-motor requirements."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "A fire-fighting vehicle admitted by the rideable-device alternative is not thereby established to be a bicycle with an assisting electric motor."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The controlling definition expressly states that the term does not include a moped."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "underdetermined",
      "reason": "The admitting words do not establish that every qualifying self-propelled non-rail vehicle permitted by this contract is a bicycle with an assisting electric motor."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The controlling definition expressly states that the term does not include a motorcycle."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "underdetermined",
      "reason": "Official service and identifying equipment do not ensure that every admitted rideable device carries the proposed bicycle-with-assisting-motor covering class."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract describes a person, including a person using a mobility device, rather than the rideable device being defined."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person with specified assistance, not a rideable device possessing the quoted equipment."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "underdetermined",
      "reason": "The quoted two-or-three-wheel requirement does not prohibit operation on tracks, and the rail-vehicle contract specifies no incompatible wheel count."
    },
    {
      "class": "ru.school_bus",
      "verdict": "underdetermined",
      "reason": "School designation and markings do not establish a wheel count or equipment configuration incompatible with every device the words admit."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "Passenger hire and identifying markings do not rule out a two- or three-wheeled device satisfying the admitting words."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The contract's service, body and livery descriptions do not establish that every member conflicts with the quoted wheel and equipment requirements."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "underdetermined",
      "reason": "Being drawn by another vehicle or forming a combination is not expressly incompatible with the quoted rideability, wheel-count and equipment requirements."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "underdetermined",
      "reason": "Public transit service and identifying displays impose no contractual wheel-count or equipment restriction that establishes exclusion."
    },
    {
      "class": "ru.truck",
      "verdict": "underdetermined",
      "reason": "A goods-carrying body does not establish a wheel count or equipment configuration that necessarily conflicts with the admitting words."
    }
  ]
}

